mapper.select:
SELECT COUNT(d.id)
FROM doctor d
    LEFT JOIN medical_dept_sub_doctor mdsd ON mdsd.doctor_id = d.id
    LEFT JOIN medical_dept_sub mds ON mdsd.dept_sub_id = mds.id
    LEFT JOIN medical_dept md ON mds.dept_id = md.id
WHERE 1 = 1

    AND d.name LIKE CONCAT('%',#{name},'%')


    AND md.id = #{deptId}


    AND d.degree = #{degree}


    AND d.job = #{job}


    AND d.recommended = #{recommended}


    AND d.`status` = #{status}

SELECT md.`name` deptName, d.school school, mds.`name` subName, d.sex sex, d.`name` `name`, d.degree degree, d.tel tel, d.id id, d.job job, d.recommended recommended, d.`status` status FROM doctor d LEFT JOIN medical_dept_sub_doctor mdsd ON mdsd.doctor_id = d.id LEFT JOIN medical_dept_sub mds ON mdsd.dept_sub_id = mds.id LEFT JOIN medical_dept md ON mds.dept_id = md.id WHERE 1 = 1
AND d.name LIKE CONCAT('%',#{name},'%')
AND md.id = #{deptId}
AND d.degree = #{degree}
AND d.job = #{job}
AND d.recommended = #{recommended}
AND d.`status` = #{status}
ORDER BY md.id ${order}
LIMIT #{length} OFFSET #{start}

mapper.delete:
DELETE FROM doctor
WHERE id IN

    #{one}

mapper.update:
UPDATE doctor
SET photo = #{photo}
WHERE id = #{id}
